SELECT id, txn_type, txn_time, amount, SUM(amount) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_amount, LAG(amount, 1) OVER (PARTITION BY txn_type ORDER BY txn_time, id) prev_amount FROM transactions WHERE NOT is_flagged ORDER BY txn_type;
